import re

ROOT1 = r"C:\HermesPortable\home\scripts\blog-automation\haustier-zentrum"
ROOT2 = r"C:\HermesPortable\home\spaces\bewusstsein\haustier-zentrum"

def fix_cookie_banner(filepath):
    """Fix cookie banner in one HTML file: remove 'show' from div class, update onclick, add init script."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    original = content
    modified = False

    # Check if this file has the cookie banner
    if 'cookie-banner' not in content:
        return False

    # Remove 'show' from cookie banner div class
    content = content.replace(
        '<div class="cookie-banner show" id="cookieBanner">',
        '<div class="cookie-banner" id="cookieBanner">'
    )
    if content != original:
        modified = True

    # Update the onclick to also save to localStorage
    content = content.replace(
        'onclick="document.getElementById(\'cookieBanner\').classList.remove(\'show\')"',
        'onclick="localStorage.setItem(\'cookieConsent\',\'1\');document.getElementById(\'cookieBanner\').classList.remove(\'show\')"'
    )
    if content != original and not modified:
        modified = True

    if not modified:
        return False

    # Add init script before </body> - checks localStorage and shows banner if no consent
    cookie_script = '''<script>
// Cookie-Consent: Banner nur anzeigen wenn nicht bereits akzeptiert
if(!localStorage.getItem('cookieConsent')){
  document.getElementById('cookieBanner')?.classList.add('show');
}
</script>
</body>'''

    content = content.replace('</body>', cookie_script)

    with open(filepath, 'w', encoding='utf-8') as f:
        f.write(content)

    return True

# Fix all files in ROOT1 (blog-automation - the main repo with all articles)
count1 = 0
for dirpath, dirnames, filenames in os.walk(ROOT1):
    for fn in filenames:
        if fn.endswith('.html'):
            fp = os.path.join(dirpath, fn)
            if fix_cookie_banner(fp):
                count1 += 1
                print(f"  FIXED: {os.path.relpath(fp, ROOT1)}")

print(f"\n--- ROOT1 ({ROOT1}): {count1} files fixed ---")

# Fix all files in ROOT2 (bewusstsein repo)
count2 = 0
for dirpath, dirnames, filenames in os.walk(ROOT2):
    for fn in filenames:
        if fn.endswith('.html'):
            fp = os.path.join(dirpath, fn)
            if fix_cookie_banner(fp):
                count2 += 1
                print(f"  FIXED: {os.path.relpath(fp, ROOT2)}")

print(f"\n--- ROOT2 ({ROOT2}): {count2} files fixed ---")
print(f"\nTOTAL: {count1 + count2} files fixed")
"}

