def fix_cookie_banner(filepath):
    """Fix cookie banner in one HTML file: remove 'show' from div class, update onclick, add init script."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    original = content
    modified = False

    # Check if this file has the cookie banner
    if 'cookie-banner' not in content:
        return False

    # Remove 'show' from cookie banner div class
    content = content.replace(
        '<div class="cookie-banner show" id="cookieBanner">',
        '<div class="cookie-banner" id="cookieBanner">'
    )
    if content != original:
        modified = True

    # Update the onclick to also save to localStorage
    content = content.replace(
        'onclick="document.getElementById(\'cookieBanner\').classList.remove(\'show\')"',
        'onclick="localStorage.setItem(\'cookieConsent\',\'1\');document.getElementById(\'cookieBanner\').classList.remove(\'show\')"'
    )
    if content != original and not modified:
        modified = True

    if not modified:
