{"code": "import json, urllib.request, time, re, os

queue_url = "http://127.0.0.1:8283"
output_dir = r"C:\Users\logga\gen_queue_outputs"
target_dir = r"C:\HermesPortable\home\scripts\blog-automation\haustier-zentrum\images"

# Define all needed images with their prompts
images_to_gen = [
    {
        "slug": "golden-retriever",
        "prompt": "cute golden retriever dog sitting on green grass in sunny meadow, golden fur gleaming, happy friendly expression, soft cartoon illustration style, warm colors, childrens book illustration, cute animal character design",
        "negative": "photorealistic, 3d render, photograph, realistic texture, hyperrealistic, text, watermark, signature, ugly, deformed"
    },
    {
        "slug": "deutscher-schaeferhund",
        "prompt": "majestic german shepherd dog standing proudly on a hill, intelligent alert expression, black and tan fur, strong athletic build, soft cartoon illustration style, warm earthy colors, childrens book illustration, cute animal character design",
        "negative": "photorealistic, 3d render, photograph, realistic texture, hyperrealistic, text, watermark, signature, ugly, deformed"
    },
    {
        "slug": "maine-coon-katze",
        "prompt": "large fluffy maine coon cat with tufted ears and bushy tail, majestic long fur, soft cartoon illustration style, warm colors, childrens book illustration, cute animal character design, cozy indoor setting",
        "negative": "photorealistic, 3d render, photograph, realistic texture, hyperrealistic, text, watermark, signature, ugly, deformed"
    },
    {
        "slug": "meerschweinchen-haltung",
        "prompt": "two cute guinea pigs sitting in a cozy habitat with hay, one orange and white one black and white, soft cartoon illustration style, warm colors, childrens book illustration, cute animal character design, friendly expression",
        "negative": "photorealistic, 3d render, photograph, realistic texture, hyperrealistic, text, watermark, signature, ugly, deformed"
    }
]

def gen_via_queue(prompt, negative="", model="sdxl-lightning", steps=4):
    data = json.dumps({
        "model": model,
        "prompt": prompt,
        "negative_prompt": negative,
        "steps": steps
    }).encode()
    req = urllib.request.Request(f"{queue_url}/generate", data=data,
                                  headers={"Content-Type": "application/json"})
    resp = json.loads(urllib.request.urlopen(req, timeout=30).read())
    jid = resp["job_id"]
    print(f"  Queued {jid}")
    return jid

# Queue all jobs
print("=== QUEUEING IMAGES ===")
job_ids = []
for img in images_to_gen:
    try:
        jid = gen_via_queue(img["prompt"], img["negative"])
        job_ids.append((jid, img["slug"]))
        print(f"  ✅ {img['slug']} - {jid}")
    except Exception as e:
        print(f"  ❌ {img['slug']} - {e}")

print(f"\n=== POLLING JOBS ===")
for jid, slug in job_ids:
    for attempt in range(60):
        time.sleep(2)
        try:
            st = json.loads(urllib.request.urlopen(f"{queue_url}/status/{jid}", timeout=10).read())
            if st["status"] == "done":
                output_path = st.get("output_path", "")
                print(f"  ✅ {slug} -> {output_path}")
                break
            if st["status"] == "failed":
                err = st.get("error", "")
                if '"status": "success"' in err or '"output_path"' in err:
                    m = re.search(r'"output_path": "([^"]+)"', err)
                    if m:
                        output_path = m.group(1).replace("\\\\", "/")
                        print(f"  ✅ {slug} (false positive) -> {output_path}")
                        break
                print(f"  ❌ {slug} failed: {err[:100]}")
                break
        except Exception as e:
            print(f"  ⚠️  {slug} poll error: {e}")
    else:
        print(f"  ⏰ {slug} timed out")
"}

